mapper.select:
select appeal_id, case_id, action_id, appellant_id, reason, evidence,
       status, reviewer_id, review_result, review_time, create_time
from lf_appeal

    status = #{status}
    and appellant_id = #{appellantId}
    and action_id = #{actionId}

order by create_time desc, appeal_id desc

mapper.insert:
insert into lf_appeal (
    case_id, action_id, appellant_id, reason, evidence, status, create_time
) values (
    #{caseId}, #{actionId}, #{appellantId}, #{reason}, #{evidence}, 'SUBMITTED', sysdate()
)

mapper.select:
select count(1)
from lf_appeal
where action_id = #{actionId}
  and appellant_id = #{appellantId}
  and status = 'SUBMITTED'
